  ('ca095dbc-5a77-53a3-9a48-29c465dfcc7e', 'journal-posts', 'tacugama-krio', 0, 'published', '{"slug":"tacugama-krio","category":"wildlife","title":"Tacugama Chimpanzee Sanctuary & Krio","date":"2026-05-06","excerpt":"A field note from a Tacugama visit paired with Freetown’s Krio story, from a published Tourism Is Life journal post.","body":"Tourism Is Life published this journal entry after conducting a Tacugama Chimpanzee Sanctuary visit together with a Krio heritage programme. The sanctuary sits in forest above Freetown; the Krio story sits in the city below. Together they are a concise introduction to the Western Circuit.\n\nFor current opening hours and group size limits, request a date-specific quote rather than treating this article as an operations manual.","image":{"media":"img_5dd1fda75a33445a","alt":"Chimpanzees at Tacugama Chimpanzee Sanctuary near Freetown, Sierra Leone"}}'::jsonb, 1, '253ab8b8-cbcf-511a-b613-7d2bccdf07a2'),
  ('28f3afa3-ff22-5ec2-a313-301b5aed376b', 'journal-posts', 'oasis-overland-group', 1, 'published', '{"slug":"oasis-overland-group","category":"case-studies","title":"Oasis Overland Group","date":"2024-12-20","excerpt":"Ground handling note for an Oasis Overland group, from the public Tourism Is Life journal.","body":"This public journal title records work with an Oasis Overland group. Operational details (headcount, routing, and commercial terms) are not republished here.\n\nOperators looking for similar Sierra Leone ground handling should use the Partner With Us enquiry.","image":{"media":"img_52b161dc571cf5bb","alt":"Overland landscape in Sierra Leone"}}'::jsonb, 1, 'e3942d88-7a75-5c25-8593-800f1aa3e2d2'),
  ('c332966d-25b4-5af4-97c0-4795e57b951e', 'journal-posts', 'keadventure-ultimate-sierra-leone', 2, 'published', '{"slug":"keadventure-ultimate-sierra-leone","category":"case-studies","title":"KE Adventure: Ultimate Sierra Leone","date":"2024-12-20","excerpt":"A public journal title documenting a KE Adventure programme in Sierra Leone.","body":"Tourism Is Life listed this KE Adventure programme among recent posts. It signals inbound adventure-operator work; it is not a copy of KE’s own itinerary.\n\nAdventure brands wanting a Sierra Leone DMC should send dates and a draft routing via the partner form.","image":{"media":"img_e3c729e81afbc790","alt":"Mount Bintumani, Sierra Leone highest peak"}}'::jsonb, 1, '3c49e125-bb5c-5e1d-930a-86221099b98a'),
  ('e7a1d7b3-d76e-5e38-8665-8e0aaf92f0c1', 'journal-posts', 'eighth-homecoming-pilgrims', 3, 'published', '{"slug":"eighth-homecoming-pilgrims","category":"culture","title":"8th Homecoming Pilgrims","date":"2024-12-20","excerpt":"Journal title from the public site marking a Homecoming pilgrims programme.","body":"The 8th Homecoming Pilgrims tour is listed on the public Tourism Is Life journal. Diaspora homecoming travel is a recurring Sierra Leone theme: Bunce Island, Freetown, and family reconnection.\n\nIf you are planning a similar pilgrimage, request a quote. Group history and routing are confirmed privately.","image":{"media":"img_0f71a82d2d92ac0d","alt":"Fortress wall at Bunce Island, Sierra Leone River"}}'::jsonb, 1, 'da3eebfe-383a-587b-99b0-c16185a1b582'),
