  ('15681671-2d95-55f7-933d-80309bed2e2e', '6b0d51d9-c75a-57aa-998b-99f4e1420c5c', 1, '{"slug":"b2b","label":"B2B Insights"}'::jsonb),
  ('253ab8b8-cbcf-511a-b613-7d2bccdf07a2', 'ca095dbc-5a77-53a3-9a48-29c465dfcc7e', 1, '{"slug":"tacugama-krio","category":"wildlife","title":"Tacugama Chimpanzee Sanctuary & Krio","date":"2026-05-06","excerpt":"A field note from a Tacugama visit paired with Freetown’s Krio story, from a published Tourism Is Life journal post.","body":"Tourism Is Life published this journal entry after conducting a Tacugama Chimpanzee Sanctuary visit together with a Krio heritage programme. The sanctuary sits in forest above Freetown; the Krio story sits in the city below. Together they are a concise introduction to the Western Circuit.\n\nFor current opening hours and group size limits, request a date-specific quote rather than treating this article as an operations manual.","image":{"media":"img_5dd1fda75a33445a","alt":"Chimpanzees at Tacugama Chimpanzee Sanctuary near Freetown, Sierra Leone"}}'::jsonb),
  ('e3942d88-7a75-5c25-8593-800f1aa3e2d2', '28f3afa3-ff22-5ec2-a313-301b5aed376b', 1, '{"slug":"oasis-overland-group","category":"case-studies","title":"Oasis Overland Group","date":"2024-12-20","excerpt":"Ground handling note for an Oasis Overland group, from the public Tourism Is Life journal.","body":"This public journal title records work with an Oasis Overland group. Operational details (headcount, routing, and commercial terms) are not republished here.\n\nOperators looking for similar Sierra Leone ground handling should use the Partner With Us enquiry.","image":{"media":"img_52b161dc571cf5bb","alt":"Overland landscape in Sierra Leone"}}'::jsonb),
  ('3c49e125-bb5c-5e1d-930a-86221099b98a', 'c332966d-25b4-5af4-97c0-4795e57b951e', 1, '{"slug":"keadventure-ultimate-sierra-leone","category":"case-studies","title":"KE Adventure: Ultimate Sierra Leone","date":"2024-12-20","excerpt":"A public journal title documenting a KE Adventure programme in Sierra Leone.","body":"Tourism Is Life listed this KE Adventure programme among recent posts. It signals inbound adventure-operator work; it is not a copy of KE’s own itinerary.\n\nAdventure brands wanting a Sierra Leone DMC should send dates and a draft routing via the partner form.","image":{"media":"img_e3c729e81afbc790","alt":"Mount Bintumani, Sierra Leone highest peak"}}'::jsonb),
  ('da3eebfe-383a-587b-99b0-c16185a1b582', 'e7a1d7b3-d76e-5e38-8665-8e0aaf92f0c1', 1, '{"slug":"eighth-homecoming-pilgrims","category":"culture","title":"8th Homecoming Pilgrims","date":"2024-12-20","excerpt":"Journal title from the public site marking a Homecoming pilgrims programme.","body":"The 8th Homecoming Pilgrims tour is listed on the public Tourism Is Life journal. Diaspora homecoming travel is a recurring Sierra Leone theme: Bunce Island, Freetown, and family reconnection.\n\nIf you are planning a similar pilgrimage, request a quote. Group history and routing are confirmed privately.","image":{"media":"img_0f71a82d2d92ac0d","alt":"Fortress wall at Bunce Island, Sierra Leone River"}}'::jsonb),
  ('5737e618-98fa-5ccd-a538-42efe2e71e1d', '4e91c71f-84fa-5a1b-92ee-475761cfa426', 1, '{"id":"handling","title":"Cruise Ship Handling","body":"Destination management for cruise calls at Freetown, from arrival coordination to shore programmes.","image":{"media":"img_b162c6ff5cca72d9","alt":"Freetown port and harbour shipping"}}'::jsonb),
  ('3e59549f-9eeb-5975-a215-e05d76f3e070', '53c930fd-2fa9-5ce6-a3d1-08c49671466b', 1, '{"id":"excursions","title":"Shore Excursions","body":"Six primary shore programmes covering the city, heritage islands, rainforest, wildlife, and peninsula beaches.","image":{"media":"img_074fdb471407d6bf","alt":"A busy market street in central Freetown, Sierra Leone"}}'::jsonb),
  ('c0b4e970-ad27-5f76-9213-36dd4534c357', '5317a5bf-2e30-57c8-83c9-738b48be7ad8', 1, '{"id":"overland","title":"Overland Journeys","body":"Overland experiences beyond the immediate quay, arranged as part of cruise destination services.","image":{"media":"img_dcaf420486617fe8","alt":"Peninsula coastline south of Freetown"}}'::jsonb),
