  ('f22d12e7-4d40-59ca-b364-d00809c94fcb', 'f2a56e21-1a19-59f2-afb8-e3a6e0105f10', 1, '{"id":"destination","title":"Destination Services","body":"Transportation, tours, excursions, hotels, and related destination services as a full-service DMC.","image":{"media":"img_c7642d6261a3e30c","alt":"The Cotton Tree in central Freetown"}}'::jsonb),
  ('8a47c22a-47d3-583c-8c56-5c7dd7c60e13', '0dd6342d-13e5-5b37-a36a-85dc37c4228e', 1, '{"id":"support","title":"24-Hour Support","body":"Once a request is confirmed, a 24-hour contact person is provided for the call.","image":{"media":"img_bfc97b693f64cff7","alt":"Aerial view of Freetown and the harbour hills"}}'::jsonb),
  ('ef9fab2e-229d-596e-8d17-08dd37e5b73b', '0ce19759-e47b-5c96-b03f-c801e3e5ef94', 1, '{"id":"freetown-city-tour","name":"Freetown City Tour","destination":"Freetown","summary":"A guided city programme covering major historical and cultural attractions in Freetown.","itineraryNotes":"Stops described in the proposal include the Cotton Tree, National Museum, Maroon Church, Railway Museum, market, and Old Fourah Bay College.","activities":["Sightseeing"],"experienceTags":["culture","history"],"groupMin":120,"groupMax":500,"departure":"Queen Elizabeth II Quay","inclusions":["Air-conditioned bus","Experienced driver","English-speaking guide","Sightseeing","Lunch"],"image":{"media":"img_c7642d6261a3e30c","alt":"The historic Cotton Tree in Freetown, wrapped in the Sierra Leone flag"}}'::jsonb),
  ('c1a9817f-720c-59bd-961d-e26dbf0e5474', '25869bea-2f8f-53b0-b4fc-50de3109223e', 1, '{"id":"bunce-tasso","name":"Bunce Island & Tasso Island","destination":"Bunce Island","summary":"A heritage excursion to Bunce Island and Tasso Island on the Sierra Leone River.","itineraryNotes":"The experience includes both Bunce Island and Tasso Island.","activities":["Sightseeing","Heritage visit"],"experienceTags":["history","culture"],"groupMin":25,"groupMax":75,"departure":"Queen Elizabeth II Quay","inclusions":["Air-conditioned bus","Experienced driver","English-speaking guide","Sightseeing","Lunch"],"image":{"media":"img_0f71a82d2d92ac0d","alt":"Fortress wall at Bunce Island on the Sierra Leone River"}}'::jsonb),
  ('2da4800d-ebe5-5891-93b2-a5759eb43ee8', 'a36586e1-efad-5eb4-ad1e-eddb18c5a020', 1, '{"id":"tacugama","name":"Tacugama Chimpanzee Sanctuary","destination":"Tacugama","summary":"A rainforest sanctuary visit with a guided tour and chimpanzee-related activities.","itineraryNotes":"The proposal describes a rainforest sanctuary experience, a guided tour, and chimpanzee-related activities.","activities":["Wildlife viewing","Guided sanctuary tour"],"experienceTags":["wildlife","nature"],"groupMin":30,"groupMax":200,"departure":"Queen Elizabeth II Quay","inclusions":["Air-conditioned bus","Experienced driver","English-speaking guide","Sightseeing","Lunch"],"image":{"media":"img_5dd1fda75a33445a","alt":"Chimpanzees at Tacugama Chimpanzee Sanctuary near Freetown"}}'::jsonb),
  ('7f042516-5315-59ae-859a-644934e86c06', 'e6b93e9e-1fc9-5ee2-a609-e808175890b3', 1, '{"id":"banana-island","name":"Banana Island","destination":"Banana Island","summary":"A coastal island day with water activities and a seafood lunch on the beach.","itineraryNotes":"Activities described include diving, snorkelling, paddle boating, swimming, and relaxation.","activities":["Diving","Snorkelling","Paddle boating","Swimming","Relaxation"],"experienceTags":["beach","adventure","nature"],"groupMin":120,"groupMax":200,"departure":"Queen Elizabeth II Quay","inclusions":["Air-conditioned bus","Experienced driver","English-speaking guide","Sightseeing","Seafood lunch on the beach"],"image":{"media":"img_9c90d5eb4b20c621","alt":"Banana Island off the Freetown Peninsula, Sierra Leone"}}'::jsonb),
  ('4ada463b-a565-5e70-a7fa-7d78339fb0b7', '1cc9fd02-0418-5923-b561-08dea64f52e9', 1, '{"id":"bird-watching","name":"Bird Watching","destination":"River No. 2","summary":"Rainforest birding on a trail that ends at River No. 2 beach.","itineraryNotes":"The experience includes rainforest birding and a trail ending at River No. 2 beach.","activities":["Bird watching","Rainforest trail"],"experienceTags":["nature","wildlife"],"groupMin":12,"groupMax":25,"departure":"Queen Elizabeth II Quay","inclusions":["Air-conditioned bus","Experienced driver","English-speaking guide","Sightseeing","Lunch"],"image":{"media":"img_3485d870528f5864","alt":"River Number Two beach, where the bird-watching trail ends"}}'::jsonb),
  ('3d884cca-486d-59f7-8f3a-ef7a5b05f305', '04395129-53b9-5181-a9dc-9f5f0aabba5a', 1, '{"id":"peninsula-beaches","name":"Peninsula Beaches","destination":"Peninsula beaches","summary":"A peninsula beach programme with sport, water, and community activities.","itineraryNotes":"Activities described include surfing, beach volleyball, beach football, canoe racing, surfing competitions, community engagement, and storytelling.","activities":["Surfing","Beach volleyball","Beach football","Canoe racing","Community engagement","Storytelling"],"experienceTags":["beach","adventure","culture"],"groupMin":30,"groupMax":200,"departure":"Queen Elizabeth II Quay","inclusions":["Air-conditioned bus","Experienced driver","English-speaking guide","Sightseeing","Lunch"],"image":{"media":"img_dcaf420486617fe8","alt":"Boats and shoreline at Tokeh Beach on the Freetown Peninsula"}}'::jsonb),
  ('c4b66256-4722-5bc5-b38f-431096c2db81', '0128bb8e-f5dd-57d2-a4a7-292a6a93dce2', 1, '{"id":"freetown","name":"Freetown","summary":"Sierra Leone’s capital and the starting point for city sightseeing: Cotton Tree, museums, churches, markets, and Old Fourah Bay College.","image":{"media":"img_c7642d6261a3e30c","alt":"The historic Cotton Tree in Freetown with the Sierra Leonean flag"}}'::jsonb),
  ('02896625-c422-51e0-843c-b85a879fd2db', 'd2980d74-8986-5eb5-b3ee-310465902a7a', 1, '{"id":"bunce-island","name":"Bunce Island","summary":"A heritage island in the Sierra Leone River, visited together with neighbouring Tasso Island.","image":{"media":"img_72510ed289e3e016","alt":"Bunce and Tasso Islands, Sierra Leone River"}}'::jsonb),
  ('1dddabaa-119d-5406-9105-dffcd36234dc', '983cc306-02a2-5de0-a62f-10ad7982e1c5', 1, '{"id":"tacugama","name":"Tacugama","summary":"A rainforest chimpanzee sanctuary in the hills above Freetown, visited as a guided shore programme.","image":{"media":"img_5dd1fda75a33445a","alt":"Chimpanzees in forest at Tacugama Sanctuary"}}'::jsonb),
  ('eb887f28-10ca-5cb4-8353-74b0c1441f3b', 'd1e3dce5-36a4-5323-8ef8-1ff3a9377b4c', 1, '{"id":"banana-island","name":"Banana Island","summary":"An island shore day with diving, snorkelling, paddle boating, swimming, and a seafood lunch on the beach.","image":{"media":"img_9c90d5eb4b20c621","alt":"Banana Island coastline off Sierra Leone"}}'::jsonb),
  ('298467d2-b0ed-5db9-beae-8c8a0f9c5783', '8a50ce78-71ec-532b-ad97-c507dd5d12a8', 1, '{"id":"river-no-2","name":"River No. 2","summary":"The beach at the end of the rainforest birding trail offered as a shore excursion.","image":{"media":"img_3485d870528f5864","alt":"River Number Two Village Beach on the Freetown Peninsula"}}'::jsonb),
  ('fe1bb846-f025-5f25-bd6c-6a8aa5706412', '4f46ca00-0d38-509a-8e5e-f5c2aaadc4b2', 1, '{"id":"peninsula-beaches","name":"Peninsula beaches","summary":"Western Area peninsula beaches used for surfing, beach sports, canoe racing, and community-hosted activities.","image":{"media":"img_b35d8b044e6e7cd3","alt":"Lumley Beach in Freetown, Sierra Leone"}}'::jsonb),
